<script>
 import {keyboardScroll} from "$lib/table-scroll.js";
 import {page} from '$app/state';
 import {networkRows} from '$lib/system-health.js';
 import {numeric,formatValue} from '$lib/energy.js';
 import EnergyFlow from './EnergyFlow.svelte';
 import BatteryGauge from './BatteryGauge.svelte';
 import HistoryChart from './HistoryChart.svelte';
 import PowerTrend from './PowerTrend.svelte';
 let {data}=$props();
 let search=$state(''),community=$state(''),status=$state('');
 let rows=$derived(networkRows(data));
 let filtered=$derived(rows.filter(r=>(!community||r.node.community_id===community)&&(!status||r.state.key===status)&&(r.node.display_name+' '+r.node.reference+' '+r.node.location_label).toLowerCase().includes(search.toLowerCase())));
 let current=$derived(rows.find(r=>r.node.id===data.node?.id));
 let metrics=$derived(current?.snapshot?.measurements||{});
 const tabs=[['live','Live overview'],['equipment','Equipment'],['history','Energy history'],['diagnostics','Diagnostics & events']];
 let tab=$derived(tabs.some(([key])=>key===page.url.searchParams.get('tab'))?page.url.searchParams.get('tab'):'live');
 const href=(node=data.node?.id,view=tab,range=data.range||'7d')=>{const params=new URLSearchParams({...(data.preview?{view:'health'}:{}),...(node?{node}:{}),tab:view,range});return (data.preview?'/admin-preview':'/admin/health')+'?'+params;};
 const nodeHref=(view='connection')=>data.preview?'/admin-preview?view=nodes':'/admin/nodes/'+data.node.id+'?tab='+view;
 const date=value=>value&&Number.isFinite(Date.parse(value))?new Intl.DateTimeFormat('en-ZW',{dateStyle:'medium',timeStyle:'medium',timeZone:'Africa/Harare'}).format(new Date(value)):'Not reported';
 let devices=$derived(data.simulated?data.simulatedDevices||[]:data.check?.revision===current?.connection?.revision?data.check?.result?.devices||[]:[]);
 let alerts=$derived(data.alerts.filter(a=>a.node_id===data.node?.id));
 let history=$derived.by(()=>{const result={solar:[],consumption:[]};for(const metric of ['solar','consumption'])result[metric]=(data.intervals||[]).filter(r=>r.node_id===data.node?.id&&r.metric===metric).map(r=>({time:r.interval_start,value:numeric(r.energy_kwh)}));return result;});
 const electrical=[['solar','Solar production','kW',1000],['consumption','Household demand','kW',1000],['batterySoc','Battery charge','%',1],['batteryPower','Battery power','kW',1000],['batteryVoltage','Battery voltage','V',1],['batteryCurrent','Battery current','A',1],['grid','Grid power','kW',1000],['generator','Generator power','kW',1000]];
 function value(key,unit,divisor=1){const n=numeric(metrics[key]?.value);return n===null?'Not reported':formatValue(n/divisor,unit,2);}
 function download(){const records=(data.intervals||[]).filter(r=>r.node_id===data.node?.id);const rows=['interval_start,interval_end,metric,resolution,energy_kwh,data_source',...records.map(r=>[r.interval_start,r.interval_end,r.metric,r.resolution,r.energy_kwh,r.simulated?'simulated':'provider'].join(','))];const url=URL.createObjectURL(new Blob([rows.join('\n')],{type:'text/csv'}));const anchor=document.createElement('a');anchor.href=url;anchor.download='gridubuntu-'+data.node.reference+'-'+data.range+'.csv';anchor.click();URL.revokeObjectURL(url);}
</script>

<svelte:head><title>System Health ? GridUbuntu</title></svelte:head>
<div class="health-summary"><div><span>Registered nodes</span><strong>{rows.length}</strong></div><div><span>Recent reporting</span><strong>{rows.filter(r=>r.state.key==='reporting').length}</strong></div><div><span>Needs attention</span><strong>{rows.filter(r=>['unavailable','delayed','partial','attention'].includes(r.state.key)).length}</strong></div><div><span>Setup / paused</span><strong>{rows.filter(r=>['setup','paused'].includes(r.state.key)).length}</strong></div></div>
<section class="admin-panel"><div class="admin-panel-head"><div><span class="admin-eyebrow">NETWORK MONITORING</span><h2>Every node, one technical view.</h2></div><span class="admin-status">Read-only equipment monitoring</span></div><div class="health-filters"><label>Find a node<input type="search" bind:value={search} placeholder="Name, reference or location"/></label><label>Community<select bind:value={community}><option value="">All communities</option>{#each data.communities as c}<option value={c.id}>{c.name}</option>{/each}</select></label><label>Monitoring state<select bind:value={status}><option value="">All states</option>{#each [['reporting','Reporting'],['attention','Low battery'],['delayed','Readings need review'],['partial','Partial collection'],['unavailable','Unavailable / awaiting'],['setup','Setup required'],['paused','Paused'],['prototype','Prototype readings']] as [key,label]}<option value={key}>{label}</option>{/each}</select></label></div>
<div class="admin-table-scroll" use:keyboardScroll role="region" aria-label="Scrollable data table"><table class="admin-table"><thead><tr><th>Energy node</th><th>Monitoring state</th><th>Last reported · CAT</th><th>Battery</th><th>Open alerts</th><th></th></tr></thead><tbody>{#each filtered as row}<tr class:selected={data.node?.id===row.node.id}><td><strong>{row.node.display_name}</strong><small>{row.node.reference} · {row.node.location_label}</small></td><td><span class="admin-status" class:good={row.state.key==='reporting'}>{row.state.label}</span></td><td>{date(row.snapshot?.reported_at)}</td><td>{formatValue(row.snapshot?.measurements?.batterySoc?.value,'%',1)}</td><td>{data.alerts.filter(a=>a.node_id===row.node.id&&!a.acknowledged).length}</td><td><a class="admin-button secondary" href={href(row.node.id)}>Monitor →</a></td></tr>{/each}{#if !filtered.length}<tr><td colspan="6"><div class="admin-empty">No nodes match these filters.</div></td></tr>{/if}</tbody></table></div><p class="admin-help">Reporting describes data availability, not equipment condition. The current workspace lists up to 500 registered nodes; prototype readings are excluded from recent reporting counts.</p></section>

<section class="admin-panel health-platform"><div><span class="admin-eyebrow">PLATFORM & COLLECTION</span><h2>Monitoring services</h2><p class="admin-help">Configuration and request-time checks; not an uptime guarantee.</p></div><dl><div><dt>Authentication</dt><dd>{data.platformHealth?.authentication?'Configured':'Not configured'}</dd></div><div><dt>Database access</dt><dd>{data.platformHealth?.database?'Available for this request':'Not assessed'}</dd></div><div><dt>Credential encryption</dt><dd>{data.platformHealth?.credentialEncryption?'Configured':'Not configured'}</dd></div><div><dt>Protected ingestion</dt><dd>{data.platformHealth?.ingestionConfigured?'Configured':'Not configured'}</dd></div><div><dt>Collection schedule</dt><dd>{data.collector?data.collector.enabled?'Enabled · every 15 minutes':'Paused / not enabled':'Not assessed'}</dd></div><div><dt>Last scheduler HTTP result</dt><dd>{data.collector?.last_http_status||'Not reported'}</dd></div><div><dt>Last request enqueued · CAT</dt><dd>{date(data.collector?.last_enqueued_at)}</dd></div></dl><a class="admin-text-link" href={data.preview?'/admin-preview?view=settings':'/admin/settings'}>Manage platform settings →</a></section>

{#if current}
<section class="admin-panel health-selected"><div class="admin-panel-head"><div><span class="admin-eyebrow">SELECTED ENERGY NODE · {current.node.reference}</span><h2>{current.node.display_name}</h2><p class="admin-help">{current.node.location_label} · {data.communities.find(c=>c.id===current.node.community_id)?.name||'Community not assigned'}</p></div><span class="admin-status" class:good={current.state.key==='reporting'}>{current.state.label}</span></div>
<form method="GET" action={data.preview?'/admin-preview':'/admin/health'} class="health-node-picker">{#if data.preview}<input type="hidden" name="view" value="health"/>{/if}<input type="hidden" name="tab" value={tab}/><input type="hidden" name="range" value={data.range||'7d'}/><label>Monitor a specific node<select name="node" value={data.node.id}>{#each data.nodes as node}<option value={node.id}>{node.reference} · {node.display_name}</option>{/each}</select></label><button class="admin-button secondary">Open node</button></form>
<nav class="admin-detail-tabs" aria-label="System health views">{#each tabs as [key,label]}<a href={href(data.node.id,key)} class:active={tab===key} aria-current={tab===key?'page':undefined}>{label}</a>{/each}</nav>
<div class="health-context"><strong>{current.state.label}</strong><p>{current.state.detail}</p><span>Equipment condition: not assessed by monitoring connectivity alone.</span></div>
{#if tab==='live'}
 <div class="health-readings"><div><span>Last reported · CAT</span><strong>{date(current.snapshot?.reported_at)}</strong></div><div><span>Last collection attempt · CAT</span><strong>{date(current.sync?.started_at||current.connection?.last_attempt_at)}</strong></div><div><span>Source</span><strong>{data.simulated?'Local prototype':current.connection?.verified_at?'Verified provider connection':'Awaiting verification'}</strong></div></div>
 <div class="admin-two-column"><div class="health-flow"><h3>Reported energy flow</h3><EnergyFlow {metrics} simulated={data.simulated}/></div><BatteryGauge {metrics}/></div>
 {#if data.simulated}<PowerTrend reportedAt={current.snapshot?.reported_at}/>{/if}
 <h3>Electrical measurements</h3><div class="admin-table-scroll" use:keyboardScroll role="region" aria-label="Scrollable data table"><table class="admin-table"><thead><tr><th>Variable</th><th>Reported value</th><th>Reported at · CAT</th></tr></thead><tbody>{#each electrical as [key,label,unit,divisor]}<tr><td>{label}</td><td><strong>{value(key,unit,divisor)}</strong></td><td>{numeric(metrics[key]?.value)===null?'Not reported':date(metrics[key]?.reportedAt||current.snapshot?.reported_at)}</td></tr>{/each}</tbody></table></div><p class="admin-help">Battery power is positive while charging and negative while discharging. Grid power is positive for import and negative for export. Missing values are not treated as zero.</p>
{:else if tab==='equipment'}
 <h3>Reported device inventory</h3><p class="admin-help">{data.simulated?'Prototype equipment list.':'Device information comes from the last connection test for the current connection revision.'} It is not a live device-fault assessment.</p><p class="admin-help">Inventory retrieved · CAT: {data.simulated?'Prototype':devices.length?date(data.check?.tested_at):'Not reported'}</p>
 {#each devices as device}<div class="health-device"><strong>{device.name}</strong><span>Firmware: {device.firmware||'Not reported'}</span></div>{/each}{#if !devices.length}<div class="admin-empty">No current device inventory is available. Open connection setup to test the selected installation.</div>{/if}<p class="admin-help">Temperature, alarms, operating modes and device-specific fault codes are only available when collected from supported provider fields. They are not inferred from power or battery readings.</p><a class="admin-button secondary" href={nodeHref()}>Open connection setup →</a>
{:else if tab==='history'}
 <div class="admin-panel-head"><div><h3>Generation & consumption</h3><p class="admin-help">Energy in kWh · Harare time (CAT).</p></div><button class="admin-button secondary" onclick={download} disabled={!data.intervals?.length}>Export CSV ↓</button></div><div class="admin-range-tabs">{#each [['today','Today'],['7d','7 days'],['30d','30 days']] as [key,label]}<a href={href(data.node.id,'history',key)} class:active={data.range===key}>{label}</a>{/each}</div><HistoryChart {history} range={data.range||'7d'}/><p class="admin-help">{data.simulated?'Prototype history is generated for this local node.':'Only stored provider measurements are displayed.'} Missing intervals stay missing; current periods may be incomplete.</p>
{:else}
 <div class="health-diagnostic-actions"><a class="admin-button secondary" href={nodeHref()}>Connection configuration →</a><form method="POST"><input type="hidden" name="operation" value="connection.sync"/><input type="hidden" name="node_id" value={data.node.id}/><input type="hidden" name="revision" value={current.connection?.revision||1}/><button class="admin-button" disabled={data.preview||data.simulated||!current.connection?.active||!current.connection?.verified_at}>Collect latest readings</button></form></div><p class="admin-help">Collection reads provider data only. No equipment-control commands are sent. A failed collection does not prove equipment failure.</p>
 <dl class="health-diagnostics"><div><dt>Provider connection</dt><dd>{current.connection?.active?'Active configuration':'Paused / not configured'}</dd></div><div><dt>Verification</dt><dd>{date(current.connection?.verified_at)}</dd></div><div><dt>Connection test</dt><dd>{current.connection?.last_test_status||'Not tested'} · {date(current.connection?.last_test_at)}</dd></div></dl>
 <h3>Node alerts</h3>{#each alerts as alert}<div class="admin-alert-row"><div><strong>{alert.title}</strong><p>{alert.kind.replaceAll('_',' ')}</p></div>{#if alert.acknowledged}<span class="admin-status good">Acknowledged</span>{:else}<form method="POST"><input type="hidden" name="operation" value="alert.ack"/><input type="hidden" name="node_id" value={alert.node_id}/><input type="hidden" name="kind" value={alert.kind}/><input type="hidden" name="fingerprint" value={alert.fingerprint}/><button class="admin-button secondary" disabled={data.preview||data.simulated}>Acknowledge</button></form>{/if}</div>{/each}{#if !alerts.length}<p class="admin-help">No recorded alerts for this node. This is not an equipment health certification.</p>{/if}
 <h3>Collection runs</h3><div class="admin-table-scroll" use:keyboardScroll role="region" aria-label="Scrollable data table"><table class="admin-table"><thead><tr><th>Started · CAT</th><th>Collection result</th><th>Code</th></tr></thead><tbody>{#each data.runs||[] as run}<tr><td>{date(run.started_at)}</td><td>{run.status}</td><td>{run.code||'—'}</td></tr>{/each}{#if !data.runs?.length}<tr><td colspan="3">No recorded collection runs for this node.</td></tr>{/if}</tbody></table></div>
 <h3>Administrative events</h3><div class="admin-table-scroll" use:keyboardScroll role="region" aria-label="Scrollable data table"><table class="admin-table"><thead><tr><th>Time · CAT</th><th>Action</th></tr></thead><tbody>{#each data.activity||[] as event}<tr><td>{date(event.created_at)}</td><td>{event.action.replaceAll('.',' / ').replaceAll('_',' ')}</td></tr>{/each}{#if !data.activity?.length}<tr><td colspan="2">No recorded administrative events for this node.</td></tr>{/if}</tbody></table></div>
{/if}
</section>
{:else}<section class="admin-panel admin-empty"><h2>No energy nodes registered yet.</h2><p>Register an energy node to begin monitoring.</p><a class="admin-button" href={data.preview?'/admin-preview?view=nodes':'/admin/nodes'}>Register a node →</a></section>{/if}

<style>
 .health-summary{display:grid;grid-template-columns:repeat(4,1fr);gap:1px;border:1px solid #d8e3ce;border-radius:14px;overflow:hidden;background:#d8e3ce;margin-bottom:24px}.health-summary>div{padding:22px;background:#f7faf2}.health-summary span{display:block;font-size:11px;color:#61725d}.health-summary strong{display:block;font-size:32px;color:#24412f;margin-top:12px}.health-filters{display:grid;grid-template-columns:1.3fr 1fr 1fr;gap:18px;margin-bottom:24px}.health-platform{display:grid;grid-template-columns:1fr 2fr;gap:24px}.health-platform dl{display:grid;grid-template-columns:1fr 1fr;gap:20px;margin:0}.health-platform>a{grid-column:1/-1}dt{font-size:11px;color:#61725d}dd{font-size:13px;color:#24412f;margin:7px 0 0;overflow-wrap:anywhere}.selected{background:#eef4e5}.health-node-picker{display:flex;gap:14px;align-items:flex-end;margin-bottom:24px}.health-node-picker label{flex:1;max-width:600px}.health-context{padding:18px;border-left:3px solid #829e45;background:#f0f5e8;border-radius:6px;margin:22px 0}.health-context strong{font-size:14px}.health-context p{font-size:13px;line-height:1.8;margin:8px 0}.health-context>span{font-size:11px;color:#61725d}.health-readings{display:grid;grid-template-columns:repeat(3,1fr);gap:22px;padding:0 0 24px}.health-readings span{display:block;font-size:11px;color:#61725d}.health-readings strong{display:block;font-size:13px;margin-top:10px;line-height:1.8}.health-flow{padding:22px;border:1px solid #dce5d3;border-radius:14px;background:#fafcf7}.health-selected h3{font-size:16px;margin:24px 0 16px}.health-device{display:flex;align-items:center;justify-content:space-between;gap:16px;padding:20px 0;border-bottom:1px solid #dce5d3;font-size:13px}.health-device span{color:#61725d;font-size:12px}.health-diagnostic-actions{display:flex;flex-wrap:wrap;gap:14px;margin-top:24px}.health-diagnostics{display:grid;grid-template-columns:repeat(3,1fr);gap:20px;margin:24px 0}.health-selected .admin-detail-tabs{flex-wrap:wrap}.health-selected .admin-alert-row>div{flex:1}@media(max-width:1000px){.health-platform{grid-template-columns:1fr}.health-readings{grid-template-columns:1fr 1fr}}@media(max-width:640px){.health-summary{grid-template-columns:1fr 1fr}.health-summary>div{padding:18px}.health-filters,.health-platform dl,.health-readings,.health-diagnostics{grid-template-columns:1fr}.health-node-picker{flex-wrap:wrap}.health-node-picker label{flex-basis:100%}.health-node-picker button{width:100%}.health-device{align-items:flex-start;flex-direction:column}.health-diagnostic-actions>*{width:100%}.health-diagnostic-actions button{width:100%}}
</style>
